<?php declare(strict_types=1); $base=config('app.base_path'); ?><div class="page-header"><div><h1><?= $trash?'Deleted Events':'Events & Festivals' ?></h1><p>Festivals, cultural events and seasonal reasons to visit Manipur.</p></div><div class="page-actions"><?php if($trash): ?><a class="btn btn-secondary" href="<?=$base?>/tourism/events">Active</a><?php else: ?><a class="btn btn-secondary" href="<?=$base?>/tourism/events?view=trash">Trash</a><a class="btn btn-primary" href="<?=$base?>/tourism/events/create">Add Event</a><?php endif; ?></div></div><div class="card table-responsive"><table class="table"><thead><tr><th>Event</th><th>When</th><th>Location</th><th>Type</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($events as $e): ?><tr><td><strong><?=htmlspecialchars($e['title'])?></strong></td><td><?=htmlspecialchars($e['start_at'])?></td><td><?=htmlspecialchars(trim(($e['city']??'').' / '.($e['district']??''),' /'))?></td><td><?=htmlspecialchars((string)($e['event_type']??'—'))?></td><td><?=htmlspecialchars($e['status'])?></td><td><?php if($trash): ?><form method="post" action="<?=$base?>/tourism/events/<?=$e['id']?>/restore"><button class="btn btn-secondary">Restore</button></form><?php else: ?><a class="link-button" href="<?=$base?>/tourism/events/<?=$e['id']?>">View</a> <a class="link-button" href="<?=$base?>/tourism/events/<?=$e['id']?>/edit">Edit</a><?php endif; ?></td></tr><?php endforeach; if(!$events): ?><tr><td colspan="6">No events found.</td></tr><?php endif; ?></tbody></table></div>
